			try container.encode(CodingKeys.pairingCancelled, forKey: .type)
		case .linkOpened(let content):
			try container.encode(CodingKeys.linkOpened, forKey: .type)
			try container.encode(content, forKey: .content)
		case .accountSelected(let content):
			try container.encode(CodingKeys.accountSelected, forKey: .type)
			try container.encode(content, forKey: .content)
		case .signOutRequested(let content):
			try container.encode(CodingKeys.signOutRequested, forKey: .type)
			try container.encode(content, forKey: .content)
		case .devicesOpened:
			try container.encode(CodingKeys.devicesOpened, forKey: .type)
		case .deviceRevoked(let content):
			try container.encode(CodingKeys.deviceRevoked, forKey: .type)
			try container.encode(content, forKey: .content)
		case .pairingApprovalOpened(let content):
			try container.encode(CodingKeys.pairingApprovalOpened, forKey: .type)
			try container.encode(content, forKey: .content)
		case .pairingApproved(let content):
			try container.encode(CodingKeys.pairingApproved, forKey: .type)
			try container.encode(content, forKey: .content)
		case .pairingDenied(let content):
			try container.encode(CodingKeys.pairingDenied, forKey: .type)
			try container.encode(content, forKey: .content)
		case .displayLanguageChanged(let content):
			try container.encode(CodingKeys.displayLanguageChanged, forKey: .type)
			try container.encode(content, forKey: .content)
		}
	}
}

