/// A screen, panel or piece of state a shell renders from a view model.
public enum Surface: Codable, Sendable, Hashable {
	/// Where the app is: which account is active and what the shell should show at the root.
	case app
	/// The known servers and the add-server flow.
	case servers
	/// Every account on every server: the "Who's watching?" picker and the account switcher.
	case accounts
	/// Signing in to a server: password and pairing.
	case signIn
	/// The signed-in account's devices.
	case devices
	/// A pairing request this account is approving for another device.
	case pairingApproval
	/// The active account's session: user, features, display language and theme.
	case session
	/// A markdown document rendered safely; the content is the source.
	case markdown(String)

	enum CodingKeys: String, CodingKey, Codable {
		case app,
			servers,
			accounts,
			signIn,
			devices,
			pairingApproval,
			session,
			markdown
	}

	private enum ContainerCodingKeys: String, CodingKey {
		case type, content
	}

	public init(from decoder: Decoder) throws {
		let container = try decoder.container(keyedBy: ContainerCodingKeys.self)
		if let type = try? container.decode(CodingKeys.self, forKey: .type) {
			switch type {
			case .app:
				self = .app
				return
			case .servers:
				self = .servers
				return
			case .accounts:
				self = .accounts
				return
			case .signIn:
				self = .signIn
				return
			case .devices:
				self = .devices
				return
			case .pairingApproval:
				self = .pairingApproval
				return
			case .session:
				self = .session
				return
			case .markdown:
				if let content = try? container.decode(String.self, forKey: .content) {
					self = .markdown(content)
					return
				}
			}
		}
		throw DecodingError.typeMismatch(Surface.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for Surface"))
	}

	public func encode(to encoder: Encoder) throws {
		var container = encoder.container(keyedBy: ContainerCodingKeys.self)
		switch self {
		case .app:
			try container.encode(CodingKeys.app, forKey: .type)
		case .servers:
			try container.encode(CodingKeys.servers, forKey: .type)
		case .accounts:
			try container.encode(CodingKeys.accounts, forKey: .type)
		case .signIn:
			try container.encode(CodingKeys.signIn, forKey: .type)
		case .devices:
			try container.encode(CodingKeys.devices, forKey: .type)
		case .pairingApproval:
			try container.encode(CodingKeys.pairingApproval, forKey: .type)
		case .session:
			try container.encode(CodingKeys.session, forKey: .type)
		case .markdown(let content):
			try container.encode(CodingKeys.markdown, forKey: .type)
			try container.encode(content, forKey: .content)
		}
	}
}

