public enum StoreOp: Codable, Sendable, Hashable {
	case read
	case write(String)
	case delete

	enum CodingKeys: String, CodingKey, Codable {
		case read,
			write,
			delete
	}

	private enum ContainerCodingKeys: String, CodingKey {
		case type, content
	}

	public init(from decoder: Decoder) throws {
		let container = try decoder.container(keyedBy: ContainerCodingKeys.self)
		if let type = try? container.decode(CodingKeys.self, forKey: .type) {
			switch type {
			case .read:
				self = .read
				return
			case .write:
				if let content = try? container.decode(String.self, forKey: .content) {
					self = .write(content)
					return
				}
			case .delete:
				self = .delete
				return
			}
		}
		throw DecodingError.typeMismatch(StoreOp.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for StoreOp"))
	}

	public func encode(to encoder: Encoder) throws {
		var container = encoder.container(keyedBy: ContainerCodingKeys.self)
		switch self {
		case .read:
			try container.encode(CodingKeys.read, forKey: .type)
		case .write(let content):
			try container.encode(CodingKeys.write, forKey: .type)
			try container.encode(content, forKey: .content)
		case .delete:
			try container.encode(CodingKeys.delete, forKey: .type)
		}
	}
}

